def merge_intervals(intervals):
    """Merge overlapping or touching intervals into a new sorted list of lists."""
    if not intervals:
        return []

    # Sort by start time without modifying the caller's list.
    merged = []
    for start, end in sorted(intervals, key=lambda pair: (pair[0], pair[1])):
        if merged and start <= merged[-1][1]:
            merged[-1] = [merged[-1][0], max(merged[-1][1], end)]
        else:
            merged.append([start, end])

    return merged


if __name__ == "__main__":
    print(merge_intervals([]))
    print(merge_intervals([[1, 3], [2, 6], [5, 9], [10, 12]]))
    print(merge_intervals([[8, 10], [1, 3], [15, 19], [4, 6]]))
    print(merge_intervals([[1, 4], [4, 5]]))
    print(merge_intervals([[0, 1], [2, 3]]))
