def parse_duration(s):
    total = 0
    i = 0
    n = len(s)

    while i < n:
        if not (s[i].isdigit()):
            raise ValueError(f"invalid duration: {s!r}")

        start = i
        while i < n and s[i].isdigit():
            i += 1

        if i >= n or s[i] not in "hms":
            raise ValueError(f"invalid duration: {s!r}")

        unit = s[i]
        i += 1

        if unit == "h":
            total += int(s[start:i]) * 3600
        elif unit == "m":
            total += int(s[start:i]) * 60
        else:
            total += int(s[start:i])

    return total


if __name__ == "__main__":
    for value in ("1h30m", "0s", "45m", "2h3s"):
        print(value, "->", parse_duration(value))
